def unpack(destination):
 destination=Path(destination).resolve();destination.mkdir(parents=True,exist_ok=True)
 blob=base64.b85decode(PAYLOAD);assert hashlib.sha256(blob).hexdigest()==PAYLOAD_SHA256
 with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)),mode='r:') as tar:
  members=tar.getmembers();assert len(members)==len(SOURCE_MANIFEST)
  assert {m.name for m in members}==set(SOURCE_MANIFEST)
  for member in members:
   path=Path(member.name);assert member.isfile() and not path.is_absolute() and '..' not in path.parts
   target=destination/path;assert target.resolve().is_relative_to(destination) and not target.is_symlink()
   data=tar.extractfile(member).read();assert hashlib.sha256(data).hexdigest()==SOURCE_MANIFEST[member.name]
   target.parent.mkdir(parents=True,exist_ok=True);assert not target.exists() or hashlib.sha256(target.read_bytes()).hexdigest()==SOURCE_MANIFEST[member.name],'Refusing to replace modified extracted source';target.write_bytes(data)
 return destination
